    response = cloudwatch.get_metric_statistics(
        Namespace=namespace,
        MetricName=metric_name,
        Dimensions=[{
            'Name': 'InstanceId',
            'Value': 'i-0abcd1234efgh5678'
        }],
        StartTime=(datetime.utcnow() - timedelta(hours=6)),
        EndTime=datetime.utcnow(),
